// Paged history shared by both operator chat views. No writes or bot actions.
window.createHistoryView = function (getPage, changed) {
  var state = { id: '', history: [], ready: false, loading: false, error: '', nextCursor: null, incompleteLines: 0 };
  var generation = 0;
  function load(older) {
    if (!state.id || state.loading || (older && !state.nextCursor)) return Promise.resolve();
    var token = generation, id = state.id, cursor = older ? state.nextCursor : null;
    state.loading = true; state.error = ''; changed('loading');
    return getPage(id, cursor).then(function (page) {
      if (token !== generation) return;
      if (!page || !Array.isArray(page.history) || page.error) throw new Error('History unavailable');
      var previousLast = state.history[state.history.length - 1], firstNew = page.history[0];
      var gap = previousLast && firstNew && (previousLast.at < firstNew.at || previousLast.at === firstNew.at && previousLast.id < firstNew.id);
      var seen = new Map();
      state.history.concat(page.history).forEach(function (m) { if (m.at >= page.from && m.at <= page.until) seen.set(m.id, m); });
      state.history = Array.from(seen.values()).sort(function (a, b) { return a.at < b.at ? -1 : a.at > b.at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0; });
      if (older || !state.ready || !state.nextCursor && gap && page.nextCursor) state.nextCursor = page.nextCursor;
      state.ready = true; state.loading = false; state.incompleteLines = page.incompleteLines || 0;
      changed(older ? 'older' : 'latest');
    }).catch(function () {
      if (token !== generation) return;
      state.loading = false; state.error = 'Could not load older history. Retry.'; changed('error');
    });
  }
  return {
    state: state,
    select: function (id) {
      if (String(id || '') === state.id) return;
      generation++; state.id = String(id || ''); state.history = []; state.ready = false;
      state.loading = false; state.error = ''; state.nextCursor = null; state.incompleteLines = 0;
      return load(false);
    },
    refresh: function () { return load(false); },
    older: function () { return load(true); },
    controls: function () {
      var msg = state.error || (state.loading ? 'Loading history...' : 'All stored history');
      return '<div class="center" style="padding:10px;text-align:center"><span class="daypill">' + msg + '</span> ' +
        (state.nextCursor ? '<button data-history-older' + (state.loading ? ' disabled' : '') + '>Older messages</button> ' : '') +
        '<button data-history-latest' + (state.loading ? ' disabled' : '') + '>Refresh latest</button>' +
        (state.incompleteLines ? '<div>Some log records could not be read.</div>' : '') +
        (!state.history.length && !state.loading ? '<div>Recent saved messages below have no recorded dates.</div>' : '') + '</div>';
    },
    bind: function (element) {
      var old = element.querySelector('[data-history-older]'), fresh = element.querySelector('[data-history-latest]');
      if (old) old.onclick = function () { load(true); };
      if (fresh) fresh.onclick = function () { load(false); };
    }
  };
};

