// Read-only operator history. The bot's short context and delivery pipeline are unchanged.
// Index only recorded fan inputs and final Telegram-acknowledged output, never prompts/raw/generated text.
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";

export const HISTORY_PAGE = 100;
export type HistoryMessage = { id: string; at: string; role: "user" | "assistant"; content: string; delivery: "received" | "acknowledged" | "unverified"; turnId?: string };
type Index = { inode: number; offset: number; byFan: Map<string, Map<string, HistoryMessage>>; badLines: number; firstAt: string | null; busy?: Promise<void> };
const indexes = new Map<string, Index>();
const validChat = (id: string) => /^-?\d{1,16}$/.test(id);

export function messagesForTurn(row: any, identity: string): HistoryMessage[] {
  if (!row || row.mode === "simulated" || !validChat(String(row.chatId)) || !Number.isFinite(Date.parse(row.ts))) return [];
  const at = new Date(row.ts).toISOString();
  const root = typeof row.turnId === "string" ? row.turnId : identity;
  const out: HistoryMessage[] = [];
  const add = (role: HistoryMessage["role"], content: unknown, suffix: string, delivery: HistoryMessage["delivery"]) => {
    if (typeof content === "string" && content.length) out.push({ id: `${root}:${suffix}`, at, role, content, delivery, ...(row.turnId ? { turnId: row.turnId } : {}) });
  };
  add("user", row.fanText, "0", "received");
  const evidence = row.delivery;
  const acknowledged = [evidence?.text, evidence?.media, evidence?.recovery].some(a => a?.status === "acknowledged");
  const finals: string[] = !evidence || acknowledged ? (Array.isArray(row.final) ? row.final.filter((s: unknown) => typeof s === "string") : []) : [];
  const media = row.media && (!evidence || evidence.media?.status === "acknowledged") ? row.media : null;
  const note = media ? (media.free ? `[sent him free ${media.kind}: ${media.label}]` : `[locked ${media.kind} waiting for him to unlock: ${media.label}]`) : "";
  if (note && !finals.length) finals.push("");
  finals.forEach((s, i) => add("assistant", [s, i === 0 ? note : ""].filter(Boolean).join("\n"), `1:${String(i).padStart(4, "0")}`, evidence ? "acknowledged" : "unverified"));
  if (row.tip?.sent?.status === "acknowledged") add("assistant", row.tip.text, "2", "acknowledged");
  return out;
}

/** Incremental byte-offset scan, one shared scan per creator. Partial final lines are retried next time. */
async function refresh(file: string, index: Index, now: number): Promise<void> {
  let stat: fs.Stats;
  try { stat = await fs.promises.stat(file); } catch (e: any) { if (e.code === "ENOENT") return; throw e; }
  if (stat.ino !== index.inode || stat.size < index.offset) { index.inode = stat.ino; index.offset = 0; }
  if (stat.size > index.offset) {
    let pending = Buffer.alloc(0), consumed = index.offset;
    const stream = fs.createReadStream(file, { start: index.offset, end: stat.size - 1, highWaterMark: 64 * 1024 });
    for await (const chunk of stream) {
      pending = Buffer.concat([pending, chunk as Buffer]);
      let start = 0, end: number;
      while ((end = pending.indexOf(10, start)) >= 0) {
        const line = pending.subarray(start, end); consumed += end - start + 1; start = end + 1;
        if (!line.length) continue;
        let row: any;
        try { row = JSON.parse(line.toString("utf8")); } catch { index.badLines++; continue; }
        if (row.mode === "simulated" || !validChat(String(row.chatId))) continue;
        const ts = Date.parse(row.ts);
        if (!Number.isFinite(ts)) continue;
        const at = new Date(ts).toISOString();
        if (!index.firstAt || at < index.firstAt) index.firstAt = at;
        if (ts > now) continue;
        const id = createHash("sha256").update(line).digest("hex");
        const messages = messagesForTurn(row, id);
        if (!messages.length) continue;
        const fan = String(row.chatId), target = index.byFan.get(fan) ?? new Map<string, HistoryMessage>();
        for (const message of messages) target.set(message.id, message);
        index.byFan.set(fan, target);
      }
      pending = pending.subarray(start);
      index.offset = consumed;
    }
  }
}

export function pageHistory(messages: HistoryMessage[], before: string | null, now = Date.now()) {
  let cursor: { at: string; id: string } | null = null;
  if (before) {
    try { cursor = JSON.parse(Buffer.from(before, "base64url").toString("utf8")); } catch { throw new Error("Invalid history cursor"); }
    if (!cursor || typeof cursor.at !== "string" || !Number.isFinite(Date.parse(cursor.at)) || typeof cursor.id !== "string" || cursor.id.length > 200) throw new Error("Invalid history cursor");
  }
  const until = new Date(now).toISOString();
  const available = messages.filter(m => m.at <= until);
  const from = available.reduce((first, message) => message.at < first ? message.at : first, until);
  const all = available.filter(m => !cursor || m.at < cursor.at || (m.at === cursor.at && m.id < cursor.id))
    .sort((a, b) => a.at < b.at ? -1 : a.at > b.at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  const history = all.slice(-HISTORY_PAGE), hasMore = all.length > HISTORY_PAGE;
  const oldest = history[0];
  return { history, hasMore, nextCursor: hasMore && oldest ? Buffer.from(JSON.stringify({ at: oldest.at, id: oldest.id })).toString("base64url") : null, from, until, days: null, scope: "all-stored" as const };
}

export async function chatHistory(logDir: string, chatId: string, before: string | null = null, now = Date.now()) {
  if (!validChat(chatId)) throw new Error("Invalid chat id");
  if (before && before.length > 600) throw new Error("Invalid history cursor");
  const file = path.resolve(logDir, "requests.jsonl");
  let index = indexes.get(file);
  if (!index) { index = { inode: 0, offset: 0, byFan: new Map(), badLines: 0, firstAt: null }; indexes.set(file, index); }
  if (!index.busy) index.busy = refresh(file, index, now).finally(() => { index!.busy = undefined; });
  await index.busy;
  return { ...pageHistory([...index.byFan.get(chatId)?.values() ?? []], before, now),
    source: "retained-turn-logs", earliestRecordedAt: index.firstAt,
    incompleteLines: index.badLines, note: "All retained message history. Messages that were never saved cannot be restored." };
}

