// Stage 3 database checks. LOCAL ONLY: Postgres 17.6 + PostgREST (scripts/bundles-db/rig.sh) behind a small gateway that maps /rest/v1/* like
// Supabase's API gateway and can fail a table on demand. Exercises the REAL HTTP calls V2 makes (offer store, bundle/catalogue loaders, ownership
// read), the real Stage 3 migration (applied twice, and AFTER a "before" phase so a missing migration is tested too), the role model, the
// immutability trigger, and one full turn that stores the offer in the database before the card is dispatched.
//   run:  bash scripts/bundles-db/rig.sh up && npx tsx scripts/check-bundles-db.ts ; bash scripts/bundles-db/rig.sh down
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { createHmac, randomUUID } from "node:crypto";
import { execFileSync } from "node:child_process";
import { config } from "../src/config.js";
import { modelFixtureContent } from "./lib/model-fixture.js";

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "check-bundles-db-"));
config.dataDir = path.join(tmp, "data");
config.logDir = path.join(tmp, "logs");
config.mergeMs = 5;
process.env.STAR_PRICE = "real";
const realWrite = process.stdout.write.bind(process.stdout);
const say = (s: string) => realWrite(s + "\n");
console.log = () => {}; console.warn = () => {}; console.error = () => {};
process.stdout.write = (() => true) as any;

const PG = "stage3-pg-v2", REST_PORT = Number(process.env.BUNDLES_REST_PORT ?? 55462), GATEWAY_PORT = Number(process.env.BUNDLES_GATEWAY_PORT ?? 55463);
const SECRET = "stage3-local-secret-0123456789abcdef0123";
const MIGRATION = process.env.BUNDLES_MIGRATION ?? "/home/ronan/twin/twin-bot-wt-stage345/db/migrations/20261011000000_v2_bundle_offers.sql";
function psql(sql: string, file?: string): string {
  return execFileSync("docker", ["exec", "-i", PG, "psql", "-U", "postgres", "-qtAX", "-v", "ON_ERROR_STOP=1"], { input: file ? fs.readFileSync(file, "utf8") : sql, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] }).trim();
}
try { if (psql("select 1") !== "1") throw new Error("odd answer"); }
catch (e: any) { say(`NOT TESTED: the local database rig is not running (${String(e?.message ?? e).split("\n")[0].slice(0, 120)}). Run: bash scripts/bundles-db/rig.sh up`); process.exit(2); }
const rows = (sql: string): any[] => JSON.parse(psql(`select coalesce(json_agg(t), '[]'::json) from (${sql}) t`));
const dml = (sql: string): any[] => JSON.parse(psql(`with t as (${sql}) select coalesce(json_agg(t), '[]'::json) from t`));
const val = (sql: string): any => { const r = rows(sql)[0]; return r ? Object.values(r)[0] : undefined; };
const b64 = (o: any) => Buffer.from(JSON.stringify(o)).toString("base64url");
const jwt = (role: string) => { const h = b64({ alg: "HS256", typ: "JWT" }), p = b64({ role, iss: "stage3-local", exp: Math.floor(Date.now() / 1000) + 7200 }); return `${h}.${p}.${createHmac("sha256", SECRET).update(`${h}.${p}`).digest("base64url")}`; };
const SERVICE = jwt("service_role"), ANON = jwt("anon"), AUTHED = jwt("authenticated");

let fail = 0, n = 0;
const ok = (c: unknown, m: string) => { n++; if (!c) { fail++; say("FAIL " + m); } };

// ---------- the gateway ----------
const faults = { failTable: "" as string, status: 503 };
const gateway = http.createServer(async (req, res) => {
  try {
    const chunks: Buffer[] = []; for await (const c of req) chunks.push(c as Buffer);
    const url = new URL(req.url!, "http://x");
    const p = url.pathname.replace(/^\/rest\/v1/, "");
    if (faults.failTable && p.startsWith("/" + faults.failTable)) { res.writeHead(faults.status, { "content-type": "application/json" }).end(JSON.stringify({ message: "injected outage" })); return; }
    const headers: Record<string, string> = {};
    for (const k of ["authorization", "content-type", "accept", "prefer", "content-profile", "accept-profile"]) if (req.headers[k]) headers[k] = String(req.headers[k]);
    const r = await fetch(`http://127.0.0.1:${REST_PORT}${p}${url.search}`, { method: req.method, headers, body: req.method === "GET" || req.method === "HEAD" ? undefined : Buffer.concat(chunks) });
    res.writeHead(r.status, { "content-type": r.headers.get("content-type") ?? "application/json" }).end(Buffer.from(await r.arrayBuffer()));
  } catch (e: any) { if (process.env.GW_DEBUG) realWrite("gateway error: " + String(e?.stack ?? e) + "\n"); try { res.destroy(); } catch { /* gone */ } }
});
await new Promise<void>((r) => gateway.listen(GATEWAY_PORT, "127.0.0.1", r));
config.supabaseUrl = `http://127.0.0.1:${GATEWAY_PORT}`;
config.supabaseKey = SERVICE;

const rest = async (method: string, p: string, body?: unknown, role = SERVICE, prefer = "return=representation") => {
  const r = await fetch(`${config.supabaseUrl}/rest/v1/${p}`, { method, headers: { apikey: role, Authorization: `Bearer ${role}`, "Content-Type": "application/json", Prefer: prefer }, body: body === undefined ? undefined : JSON.stringify(body) });
  const t = await r.text();
  return { status: r.status, body: t ? (() => { try { return JSON.parse(t); } catch { return t; } })() : null };
};

// ---------- existing schema the loaders read (the parts of db/schema.sql they touch) ----------
psql(`
create table if not exists public.photos (id uuid primary key default gen_random_uuid(), clone_id uuid not null references public.clones(id) on delete cascade, storage_path text not null, caption text, teaser_caption text, star_value integer not null default 500, image_name text, is_nude boolean not null default false, explicitness text not null default 'none', is_free boolean not null default false, nsfw boolean not null default false, tags text[] not null default '{}', auto_desc text, telegram_file_id text, visual_description text, created_at timestamptz not null default now());
create table if not exists public.videos (id uuid primary key default gen_random_uuid(), clone_id uuid not null references public.clones(id) on delete cascade, storage_path text not null, caption text, teaser_caption text, star_value integer not null default 500, is_nude boolean not null default false, explicitness text not null default 'none', is_free boolean not null default false, nsfw boolean not null default false, tags text[] not null default '{}', auto_desc text, telegram_file_id text, visual_description text, created_at timestamptz not null default now());
create table if not exists public.photo_bundles (id uuid primary key default gen_random_uuid(), clone_id uuid not null references public.clones(id) on delete cascade, name text not null, caption text, star_price integer not null check (star_price between 1 and 8500), is_onboarding boolean not null default false, campaign_only boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.photo_bundle_items (id uuid primary key default gen_random_uuid(), bundle_id uuid not null references public.photo_bundles(id) on delete cascade, storage_path text not null, sort_order integer not null default 0, caption text, auto_desc text, visual_description text, tags text[] not null default '{}');
`);
const slug = `s3${Date.now().toString(36).slice(-6)}`;
const CLONE: string = dml(`insert into public.clones(slug, name, bot_token, starting_credits, credit_pack_size, credit_pack_price_stars, engine) values ('${slug}', 'Stage3', '7300000001:AAFtesttoken', 10, 30, 34, 'v2') returning id`)[0].id;

const media = await import("../src/media.js");
const bundles = await import("../src/bundles.js");
const offers = await import("../src/bundle-offers.js");
const pay = await import("../src/payments.js");
const { runAs } = await import("../src/context.js");
const { M, turnRig } = await import("./lib/turn-rig.js");
// Only the model is stubbed. Every other call is a REAL HTTP call to the local gateway / PostgREST.
const realFetch = globalThis.fetch;
globalThis.fetch = (async (url: any, init?: any) => {
  if (String(url).includes("openrouter.ai")) { M.requests++; return new Response(JSON.stringify({ provider: "stub", choices: [{ message: { content: modelFixtureContent(M.reply, init?.body) }, finish_reason: "stop" }], usage: {} }), { status: 200 }); }
  if (!String(url).startsWith("http://127.0.0.1:")) throw new Error("unexpected network call in a check: " + url);
  return realFetch(url, init);
}) as typeof fetch;
const restoreFetch = () => { globalThis.fetch = realFetch; };

const FAN = 6_900_000_001;
const fanRow = dml(`insert into public.users(clone_id, telegram_id, name) values ('${CLONE}', ${FAN}, 'Fan') returning id`)[0].id;
const OFFER_ID = () => randomUUID();

// ===================== BEFORE the migration =====================
psql(`drop table if exists public.v2_bundle_offers cascade; alter table public.star_transactions drop column if exists v2_offer_id;`); // repeatable
psql("notify pgrst, 'reload schema'"); await new Promise((r) => setTimeout(r, 1500));
ok(await offers.offerTableReady() === false, "before the migration: the offer table is reported unavailable (bundles stay off)");
{
  const bid = randomUUID();
  psql(`insert into public.star_transactions(id, clone_id, user_id, telegram_id, kind, feature, amount_stars, paid_at, media_type, media_id) values ('pre-${slug}', '${CLONE}', '${fanRow}', ${FAN}, 'media', 'bundle', 900, now(), 'bundle', '${bid}')`);
  await runAs(slug, () => pay.loadLiveOwnership(CLONE, FAN, 1_900_000_000_000));
  ok(runAs(slug, () => pay.ownedKeys(FAN)).has(`bundle:${bid}`), "before the migration: the ownership read falls back (no v2_offer_id column) and still sees the bundle purchase");
  ok(fs.existsSync(path.join(config.dataDir, slug, "_live_owned.json")), "...and caches it");
  psql(`delete from public.star_transactions where id='pre-${slug}'`);
}

// ===================== the migration =====================
psql("", MIGRATION);
psql("", MIGRATION); // twice: idempotent
psql("notify pgrst, 'reload schema'"); await new Promise((r) => setTimeout(r, 1500)); // Supabase does this on every DDL change
ok(val(`select count(*) from information_schema.tables where table_name='v2_bundle_offers'`) == 1 && val(`select count(*) from information_schema.columns where table_name='star_transactions' and column_name='v2_offer_id'`) == 1, "migration applies cleanly, twice");
ok(await offers.offerTableReady() === true, "after the migration: the offer table is available");
ok(val(`select relrowsecurity from pg_class where relname='v2_bundle_offers'`) === true, "row level security is on");

// ===================== roles =====================
{
  const offer = { id: OFFER_ID(), clone_id: CLONE, telegram_id: FAN, route: "ordinary", bundle_id: randomUUID(), bundle_name: "T", stored_stars: 100, quoted_stars: 100, manifest_sha256: "a".repeat(64), quoted_at: new Date().toISOString(), manifest: [{ n: 1 }, { n: 2 }] };
  ok((await rest("GET", "v2_bundle_offers?select=id", undefined, ANON)).status >= 401, "anon cannot read offers");
  ok((await rest("GET", "v2_bundle_offers?select=id", undefined, AUTHED)).status >= 401, "authenticated users cannot read offers");
  ok((await rest("POST", "v2_bundle_offers", offer, ANON)).status >= 401 && (await rest("POST", "v2_bundle_offers", offer, AUTHED)).status >= 401, "neither can insert");
  const ins = await rest("POST", "v2_bundle_offers", offer);
  ok(ins.status === 201, "service role inserts");
  ok((await rest("DELETE", `v2_bundle_offers?id=eq.${offer.id}`)).status >= 400, "even the service role cannot delete a bundle offer");
  // constraints
  const bad = async (patch: any, why: string) => ok((await rest("POST", "v2_bundle_offers", { ...offer, id: OFFER_ID(), ...patch })).status >= 400, `rejected: ${why}`);
  await bad({ manifest: [{ n: 1 }] }, "a one-file manifest");
  await bad({ manifest: Array.from({ length: 11 }, (_, i) => ({ n: i })) }, "an eleven-file manifest");
  await bad({ manifest: { a: 1 } }, "a manifest that is not an array");
  await bad({ stored_stars: 0 }, "a zero price");
  await bad({ stored_stars: 8501 }, "a price over 8500");
  await bad({ route: "telegram" }, "an unknown route");
  await bad({ manifest_sha256: "xyz" }, "a malformed manifest hash");
  await bad({ delivery_status: "sent" }, "an unknown delivery status");
  await bad({ clone_id: randomUUID() }, "an unknown creator");
  // immutability
  const upd = (patch: any) => rest("PATCH", `v2_bundle_offers?id=eq.${offer.id}`, patch);
  ok((await upd({ manifest: [{ n: 9 }, { n: 8 }] })).status >= 400, "the manifest cannot be edited");
  ok((await upd({ quoted_stars: 1 })).status >= 400 && (await upd({ stored_stars: 1 })).status >= 400, "neither price can be edited");
  ok((await upd({ bundle_id: randomUUID() })).status >= 400 && (await upd({ telegram_id: 1 })).status >= 400 && (await upd({ route: "business" })).status >= 400, "bundle, fan and route cannot be edited");
  ok((await upd({ delivery_status: "unknown" })).status === 200, "delivery status moves forward (prepared -> unknown)");
  ok((await upd({ delivery_status: "acknowledged", telegram_message_id: 5 })).status === 200, "...and unknown -> acknowledged");
  ok((await upd({ delivery_status: "rejected" })).status >= 400, "an acknowledged offer is final");
  ok(val(`select manifest_sha256 from public.v2_bundle_offers where id='${offer.id}'`) === "a".repeat(64) && val(`select jsonb_array_length(manifest) from public.v2_bundle_offers where id='${offer.id}'`) == 2, "the stored record is unchanged by all of that");
}

// ===================== the real store =====================
