  start(chatId: number): void; reset(chatId: number): void; stop(): void;
  dir(): string; logs(): string;
  chat(chatId: number): any | null; seedChat(chatId: number, c: any): void;
  fids(): Record<string, string> | null; seedFids(f: any): void;
  rows(): any[]; ledger(): any[];
