const asGirl = (slug: string, extra: Partial<Girl> = {}): Girl => ({ ...riley, slug, cloneId: `clone-${slug}`, ...extra }) as Girl;

function makeRig(o: { slug?: string; catalogue?: Item[]; mode?: "real" | "simulated"; girl?: Partial<Girl>; clock?: () => number; mergeMs?: number } = {}): Rig {
  const slug = o.slug ?? `t${++seq}`;
  const tg = new FakeTelegram();
  const hooks: Hooks = {
    wait: async () => {},
    download: async (it) => { D.calls.push(it.storagePath); if (D.error) throw D.error; return Buffer.from("FILEBYTES"); },
    ownership: async () => "cached",
  };
  let active = true;
  const deps: Deps = {
    girl: asGirl(slug, o.girl), catalogue: o.catalogue ?? CAT, api: tg.api, wait: (ms) => hooks.wait(ms), now: o.clock ?? Date.now,
    download: (it) => hooks.download(it), loadOwnership: (c, id) => hooks.ownership(c, id), isActive: () => active, mode: o.mode ?? "real",
  };
  const q = createTurnQueue(deps, o.mergeMs ?? 5);
  const dir = () => path.join(config.dataDir, slug), logs = () => path.join(config.logDir, slug);
  const file = (id: number) => path.join(dir(), `${id}.json`);
  return {
    slug, tg, hooks,
    fanNow: (chatId, text, route = {}) => { runAs(slug, () => q.queue(chatId, "@t", text, route)); },
    async fan(chatId, text, route = {}) { runAs(slug, () => q.queue(chatId, "@t", text, route)); await q.idle(); },
    idle: () => q.idle(),
    start: (chatId) => runAs(slug, () => { q.clear(chatId); resetChat(chatId); }),
    reset: (chatId) => runAs(slug, () => { q.clear(chatId); resetChat(chatId); }),
    stop: () => { active = false; q.stop(); },
    dir, logs,
    chat: (id) => { try { return JSON.parse(fs.readFileSync(file(id), "utf8")); } catch { return null; } },
    seedChat: (id, c) => { fs.mkdirSync(dir(), { recursive: true }); fs.writeFileSync(file(id), JSON.stringify(c, null, 2)); },
    fids: () => { try { return JSON.parse(fs.readFileSync(path.join(dir(), "_file_ids.json"), "utf8")); } catch { return null; } },
    seedFids: (f) => { fs.mkdirSync(dir(), { recursive: true }); fs.writeFileSync(path.join(dir(), "_file_ids.json"), JSON.stringify(f)); },
    rows: () => readJsonl(path.join(logs(), "requests.jsonl")),
    ledger: () => readJsonl(path.join(dir(), "purchases.jsonl")),
  };
}
