// Test-only adapter for pre-existing fixture strings. This deliberately does not use the production
// decoder: the mock must obey the requested wire contract independently of the implementation.
// Plain completions and background memory extraction retain their original response verbatim.
export function modelFixtureContent(legacy: string, requestBody: unknown): string {
  let body: any;
  try { body = typeof requestBody === "string" ? JSON.parse(requestBody) : requestBody; } catch { return legacy; }
  if (body?.response_format?.json_schema?.name !== "twin_reply") return legacy;
  // An empty provider response is a transport/model failure fixture, not an intentional empty caption.
  if (!legacy.trim()) return legacy;

  const markers = [...legacy.matchAll(/\[([^\[\]]*)\]/g)];
  // Preserve the existing one-commercial-action fixture: a valid media choice plus a stray tip
  // marker chooses only the media; the real pipeline must strip and ignore the embedded tip.
  const mediaWithTip = markers.length === 2 && markers.filter(m => m[1] === "tip").length === 1;
  const match = markers.length === 1 ? markers[0] : mediaWithTip ? markers.find(m => m[1] !== "tip") : undefined;
  const selection = match?.[1];
  const allowed = body.response_format.json_schema.schema?.properties?.selection?.enum;
  if (match && selection && /^(?:photo [1-9]\d*|free (?:photo|video)|video 1|bundle [1-9]\d*|tip)$/.test(selection)
      && Array.isArray(allowed) && allowed.includes(selection)) {
    const reply = legacy.slice(0, match.index!) + legacy.slice(match.index! + match[0].length);
    // Additional malformed brackets must still exercise the invalid-response path.
    if (!/[\[\]]/.test(mediaWithTip ? reply.replace("[tip]", "") : reply)) return JSON.stringify({ selection, reply: reply.trim() });
  }
  // Unknown, unlisted, malformed and multiple media markers remain visibly invalid. Never silently choose
  // a different file or repair a failure fixture into a valid model selection.
  return JSON.stringify({ selection: "none", reply: legacy });
}

