export const M = { reply: "" as string, onModel: undefined as undefined | (() => void | Promise<void>), requests: 0,
  /** Contract integration tests can bypass legacy fixture adaptation and supply the exact model bytes. */
  rawStructured: false,
  /** Stage 5: every model request body (parsed) in order, and the usage the stub reports (default: none). */
  bodies: [] as any[], usage: {} as Record<string, number>, fail: undefined as undefined | (() => boolean) };
const realFetch = globalThis.fetch;
/** Replaces global fetch with a model stub; anything else must be allowed through `passthrough` (the DB checks use fetch for HTTP). */
export function installModelStub(passthrough: (url: string) => boolean = () => false) {
  globalThis.fetch = (async (url: any, init?: any) => {
    const u = String(url);
    if (u.includes("openrouter.ai")) {
      M.requests++; try { M.bodies.push(JSON.parse(String(init?.body ?? "null"))); } catch { M.bodies.push(null); }
      await M.onModel?.();
      if (M.fail?.()) return new Response(JSON.stringify({ error: { message: "stub failure" } }), { status: 500 });
      return new Response(JSON.stringify({ provider: "stub", choices: [{ message: { content: M.rawStructured ? M.reply : modelFixtureContent(M.reply, init?.body) }, finish_reason: "stop" }], usage: M.usage }), { status: 200 });
    }
    if (u.includes("/rest/v1/star_transactions")) return new Response("[]", { status: 200 });
