}
export const restoreFetch = () => { globalThis.fetch = realFetch; };

export type Reply = undefined | "ack" | { err: Error } | { rej: [number, string] } | { result: unknown };
export class FakeTg {
  calls: { method: string; payload: any }[] = [];
  handlers: ((c: { method: string; payload: any }) => Reply | Promise<Reply>)[] = [];
  api: Api;
  private static mid = 5000;
  constructor(api?: Api) {
    this.api = api ?? new Api("1:fake"); // Stage 2B: a handler rig passes the Bot's own api so the production handlers talk to this fake
    this.api.config.use(async (_prev, method, payload: any) => {
      const c = { method, payload }; this.calls.push(c);
      for (const h of this.handlers) { const r = await h(c); if (r !== undefined) return this.respond(r, method, payload) as any; }
      return this.respond("ack", method, payload) as any;
    });
  }
  private respond(r: Reply, method: string, p: any) {
    if (r && typeof r === "object" && "err" in r) throw r.err;
    if (r && typeof r === "object" && "rej" in r) return { ok: false, error_code: r.rej[0], description: r.rej[1] };
    if (r && typeof r === "object" && "result" in r) return { ok: true, result: (r as any).result };
    const id = ++FakeTg.mid, chat = { id: p?.chat_id, type: "private" };
    if (method === "sendMessage") return { ok: true, result: { message_id: id, date: 0, chat, text: p.text } };
    if (method === "sendPhoto") return { ok: true, result: { message_id: id, date: 0, chat, photo: [{ file_id: `PH${id}`, file_unique_id: "u", width: 1, height: 1 }] } };
    if (method === "createInvoiceLink") return { ok: true, result: `https://t.me/$inv${id}` };
    if (method === "sendPaidMedia") return { ok: true, result: { message_id: id, date: 0, chat, paid_media: { star_count: p.star_count, paid_media: [{ type: "photo", photo: [{ file_id: `PM${id}`, file_unique_id: "u", width: 1, height: 1 }] }] } } };
    return { ok: true, result: true };
  }
  on(method: string, f: (c: { method: string; payload: any }) => Reply | Promise<Reply>) { this.handlers.push((c) => (c.method === method ? f(c) : undefined)); }
  of(method: string) { return this.calls.filter((c) => c.method === method); }
