    method: "POST",
    headers: { apikey: config.supabaseKey, Authorization: `Bearer ${config.supabaseKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ expiresIn: 300 }),
    signal: AbortSignal.timeout(20_000),
  });
